"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0972-01-01:0":{"b": ["Xelîfeyê Fatimî Muîz Bulukkîn kir walîyê Mexrîbê û li Qeyrewanê bi cih kir; serdema Zîriyan dest pê kir", "562089c8"], "d": ["Xelîfeyê Fatimî Muîz-Lidînillah Bulukkîn b. Zîrî tayînî walîtiya Mexrîbê kir û li Qeyrewanê bi cih kir (361/972) û navenda rêveberiya dewletê veguhast Misrê û ji herêmê veqetiya.", "26bbc5b2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0976-10-02:0":{"b": ["Piştî mirina Hekemê II., Hîşamê II. ê yazdeh-diwazdeh salî bû xelîfe.", "359fba92"], "d": ["Piştî mirina Hekemê II., Hîşamê II. ê yazdeh-diwazdeh salî bû xelîfe.", "359fba92"]},
