"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1046-08-01:0":{"b": ["Annazî Sedî li Hulwanê xutbe bi navê Îbrahîm Yînal da xwendin", "5cbe7ebb"], "d": ["Sedî b. Ebuşşewq ê ku piştî mirina Ebuşşewq (Nîsan 1046) ji mamê xwe Muhelhil xeyidî, bi komeke eşîra Şazencanê tevlî fermandarê Selçûqî Îbrahîm Yînal bû û li Hulwanê xutbe bi navê wî da xwendin (Tebax 1046); bi vî awayî welatê Annaziyan ji nufûza Selçûqiyan re vebû.", "bf9a2a58"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1047-01-01:0":{"b": ["Elî es-Suleyhî bi girtina Cebelimesarê serî hilda, xanedana Suleyhî hat avakirin", "e8ea1532"], "d": ["Elî es-Suleyhî bi girtina Cebelimesarê serî hilda, xanedana Suleyhî hat avakirin", "e8ea1532"]},
