"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1107-06-01:0":{"b": ["Surhab b. Bedr dimire (Şewal 500 / Hezîran 1107); Ebû Mensûr dikeve şûna wî.", "a1931e53"], "d": ["Surhab b. Bedr dimire (Şewal 500 / Hezîran 1107); Ebû Mensûr dikeve şûna wî.", "a1931e53"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1109-07-31:0":{"b": ["Wezîr Ehmed b. Nîzamulmulk bi artêşeke mezin şandin Alamûtê; ji ber zivistanê encam nehat girtin", "ba5263e5"], "d": ["Siltanê Selçûqî Muhammed Tapar, ji bo ku Hesen Sebbah ji holê rake, wezîrê xwe Ehmed b. Nîzamulmulk bi artêşeke mezin şand ser Alamûtê; sefer ji ber zivistanê bêencam ma. Dorpêça rastîn dê di 1117an de bihata.", "2e2a9c88"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1113-06-18:0":{"b": ["Li Helebê bi wekîlên Hesen Sebbah ên Sûriyeyê re gelek Batinî hatin kuştin", "c70cc81f"], "d": ["Siltanê Selçûqî Muhammed Tapar ji Melîkê Helebê Alparslan el-Exres û Reîsulehdas Seîd b. Bedî xwest ku Batiniyên li bajêr bên kuştin; wekîlên Hesen Sebbah ên Sûriyeyê, wek Ebû Tahir es-Saîx, Îsmaîl ed-Daî û birayê Hekîm el-Muneccim, bi gelek Batiniyan re hatin kuştin (507/1113).", "c7adbffa"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1117-01-01:0":{"b": ["Xanedana Annazî bi dawî bû (li gorî qeyda 130 salî ya Îbnulesîr)", "a533a1d6"], "d": ["Xanedana Annazî bi dawî bû (li gorî qeyda 130 salî ya Îbnulesîr)", "a533a1d6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1124-05-23:0":{"b": ["Hesen Sebbah li Alamûtê mir", "1dccca4f"], "d": ["Hesen Sebbah li Alamûtê mir", "1dccca4f"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1127-01-17:0":{"b": ["Siltan Sencer Alamût dorpêç kir; kele nehat girtin", "6b06eb0c"], "d": ["Siltanê Selçûqî Sencer di sala 521an de (1127) Alamûta navenda Îsmaîliyên Nîzarî dorpêç kir; fetha keleyê pêk nehat.", "91215716"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:0":{"b": ["Siltan Mahmûd b. Muhammed Tapar Alamût dorpêç kir; kele nehat girtin", "64d6b833"], "d": ["Siltanê Selçûqî Mahmûd b. Muhammed Tapar di sala 524an de (1130) Alamût dorpêç kir; kele neket.", "791399dc"]},
