"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1137-01-01:0":{"b": ["Fatikê II. hat kuştin; Fatikê III. b. Muhammed bû hukumdar, Surûr bû wezîr (531).", "2f2d69ac"], "d": ["Fatikê II. hat kuştin; Fatikê III. b. Muhammed bû hukumdar, Surûr bû wezîr (531).", "2f2d69ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:0":{"b": ["Piştî serkeftina Qatwanê Xarizmşah bûn peyrewên Qerexîtayan û dayîna xeracê qebûl kirin", "5719a5ee"], "d": ["Piştî ku Qerexîtayan Sencer li Qatwanê têk birin û li ser hemû Maweraunnehrê serdest bûn, heman salê Xarizmşahan jî bûn peyrewên Qerexîtayan û dayîna xeracê qebûl kirin (salane 30.000 dînar). Ev peyrewî heta 1173an ajot, ku Tekîş bi piştgiriya Qerexîtayan derket ser textê Xarizmê.", "ab6f992b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:1":{"b": ["Kakûyiyê dawîn di şerê Qatwanê de mir; li Yezdê Atabegên Yezdê cihê wan girtin", "272bdc16"], "d": ["Kakûyiyê dawîn di şerê Qatwanê de mir; li Yezdê Atabegên Yezdê cihê wan girtin", "272bdc16"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1142-02-01:0":{"b": ["Gurxan Yeh-lü Ta-şi mir; jina wî Kuyang (Tu-pu-yen) ket şûna wî", "29e8156e"], "d": ["Yekemîn hukumdarê Qerexîtayan Gurxan Yeh-lü Ta-şi (1130-1142) di Sibata 1142an (an 1143an) de mir; bi dorê jina wî Tu-pu-yen (Kuyang), kurê wî Yeh-lü Yi-lie, xwişka wî Yeh-lü-şe an naîb Pu-su-wan ketin şûna wî. Bi serkeftina Qatwanê (1141) hemû Maweraunnehr û Xarizm ketibûn bin bacê.", "5412642d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1150-01-01:0":{"b": ["Ummu Fatik Elem mir; Surûr hemû selahiyet di destê xwe de civand (545).", "5a5e3fcd"], "d": ["Ummu Fatik Elem mir; Surûr hemû selahiyet di destê xwe de civand (545).", "5a5e3fcd"]},
